<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import type {AdminDetail} from '../../../../shared/contracts';
import {validExternalUrl} from '../../../../shared/schemas';
import {adminApi,dateLabel,errorMessage,kindLabels,safeMediaUrl,isToolboxResource} from '../api';
import AdminNav from '../components/AdminNav.vue';
import ContentState from '../components/ContentState.vue';
const route=useRoute(),content=ref<AdminDetail|null>(null),busy=ref(false),error=ref(''),narrow=ref(false),mediaFailed=ref(false),copyStatus=ref('');let sequence=0;
async function load(){const current=++sequence;busy.value=true;error.value='';content.value=null;mediaFailed.value=false;try{const data=await adminApi.get(String(route.params.id));if(current===sequence)content.value=data;}catch(e){if(current===sequence)error.value=errorMessage(e);}finally{if(current===sequence)busy.value=false;}}
watch(()=>route.params.id,load,{immediate:true});
const media=computed(()=>{const c=content.value;if(!c)return [];return [...c.media].sort((a,b)=>a.role.localeCompare(b.role)||a.position-b.position).map(link=>({...link,asset:c.mediaAssets.find(a=>a.assetId===link.assetId)}));});
function url(id:string,variant:string){return safeMediaUrl(content.value?.mediaAssets.find(a=>a.assetId===id)?.variants.find(v=>v.name===variant)?.url);}
async function copyBody(){copyStatus.value='';try{await navigator.clipboard.writeText(content.value?.bodyText||'');copyStatus.value='已复制已保存正文';}catch(e){copyStatus.value='复制失败，请手动选择正文复制';}}
</script>
<template><AdminNav/><h1>预览已保存内容</h1><p class="notice">此页通过站主接口读取保存后的版本；仅供你检查，不是公开分享链接。</p><p v-if="busy">正在读取预览…</p><div v-if="error" role="alert"><p class="error">{{error}}</p><button @click="load">重试读取</button></div><template v-if="content"><ContentState :content="content"/><div class="tools"><RouterLink :to="`/admin/contents/${content.id}/edit`">返回编辑</RouterLink><button class="quiet" :aria-pressed="narrow" @click="narrow=!narrow">{{narrow?'切回宽屏预览':'按 390px 阅读宽度预览'}}</button><button v-if="isToolboxResource(content)&&content.bodyText" class="quiet" @click="copyBody">复制已保存正文</button><span v-if="copyStatus" class="muted">{{copyStatus}}</span></div><article class="card" :class="{narrow}"><span class="eyebrow">{{kindLabels[content.kind]}} {{isToolboxResource(content)?'· AI 工具箱':''}} {{content.isDemo?'· 合成样本':''}}</span><h1>{{content.title}}</h1><p class="muted">{{dateLabel(content.recordDate)}}</p><p v-if="content.category">分类：{{content.category}}</p><p v-if="content.summary">{{content.summary}}</p><section v-if="isToolboxResource(content)" class="toolbox-note"><h2>Markdown 正文预览</h2><p class="notice">当前显示已保存的 Markdown 原文；访客页渲染规则由前台实现。</p></section><p class="text" v-if="content.bodyText">{{content.bodyText}}</p><figure v-for="item in media" :key="item.assetId"><img v-if="['diaryPage','cover'].includes(item.role)&&url(item.assetId,'display')" :src="url(item.assetId,'display')" :alt="item.alt||`第 ${item.position+1} 页`" @error="mediaFailed=true"><video v-if="item.role==='video'&&url(item.assetId,'playback')" :src="url(item.assetId,'playback')" controls preload="metadata" @error="mediaFailed=true"/><figcaption v-if="item.role==='diaryPage'">第 {{item.position+1}} 页 {{item.alt}}</figcaption><a v-if="item.role==='resourceFile'&&url(item.assetId,'download')" :href="url(item.assetId,'download')">下载资源：{{item.asset?.originalName}}</a></figure><p v-if="mediaFailed" role="alert" class="error">部分媒体读取失败，请重新登录或重试读取；当前预览不完整。</p><section v-if="content.transcription"><h2>整理文字</h2><p class="text">{{content.transcription}}</p></section><section v-if="content.reflection"><h2>现在的文字旁白</h2><p class="text">{{content.reflection}}</p></section><section v-if="content.resource"><h2>资源说明</h2><p>作者：{{content.resource.author||'未填写'}} · 版本：{{content.resource.versionLabel||'未填写'}}</p><a v-if="content.resource.sourceUrl&&validExternalUrl(content.resource.sourceUrl)" :href="content.resource.sourceUrl" target="_blank" rel="noopener noreferrer">打开原出处</a><p>许可证：{{content.resource.licenseName||'未指定'}} · 再分发：{{content.resource.redistribution==='allowed'?'允许':content.resource.redistribution==='forbidden'?'禁止':'未确认'}}</p><p class="text">{{content.resource.permissionNote}}</p><p class="text">{{content.resource.usageInstructions}}</p><p class="text" v-if="content.resource.modificationNote">修改说明：{{content.resource.modificationNote}}</p></section><section v-if="content.game"><h2>作品入口</h2><a v-if="validExternalUrl(content.game.launchUrl)" :href="content.game.launchUrl" target="_blank" rel="noopener noreferrer">打开已有作品</a><p class="text">{{content.game.usageInstructions}}</p></section></article></template></template>
<style scoped>.tools{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin-bottom:24px}article{margin:auto}.narrow{max-width:390px}figure{margin:24px 0}img,video{display:block;max-width:100%;height:auto;margin:auto}figcaption{text-align:center;color:var(--muted);font-size:13px}.text{white-space:pre-wrap}a{color:var(--accent)}section{border-top:1px solid var(--line);margin-top:28px}</style>
